export const configSchema = z
  .object({
    leagues: z.array(leagueEntrySchema).min(1, "at least one league must be configured"),
  })
  .superRefine((cfg, ctx) => {
    const seen = new Set<string>();
    for (const [i, league] of cfg.leagues.entries()) {
      if (seen.has(league.id)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: `duplicate league id "${league.id}" — ids must be unique`,
          path: ["leagues", i, "id"],
        });
      }
      seen.add(league.id);
    }
  });

export const leagueEntrySchema = z
  .object({
    id: z.string().min(1, "league id (your own label) is required"),
    platform: z.enum(["sleeper", "espn"]),
    sleeper: sleeperConfig.optional(),
    espn: espnConfig.optional(),
  })
  .superRefine((entry, ctx) => {
    if (entry.platform === "sleeper" && !entry.sleeper) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `league "${entry.id}" has platform "sleeper" but no "sleeper" config block`,
        path: ["sleeper"],
      });
    }
    if (entry.platform === "espn" && !entry.espn) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `league "${entry.id}" has platform "espn" but no "espn" config block`,
        path: ["espn"],
      });
    }
  });

export const protectRuleSchema = z
  .object({
    /** Match by platform player id (exact) ... */
    playerId: z.string().optional(),
    /** ... or by display name (case-insensitive), e.g. "Ja'Marr Chase". */
    playerName: z.string().optional(),
    /** Which movements are forbidden. Default: both. */
    actions: z.array(z.enum(["trade", "drop"])).default(["trade", "drop"]),
  })
  .refine((r) => r.playerId || r.playerName, {
    message: "a protect rule needs either playerId or playerName",
  });

export const rulesConfigSchema = z.object({
  /** manual = approve every action; auto = execute anything that passes blocks. */
  mode: z.enum(["manual", "auto"]).default("manual"),
  protect: z.array(protectRuleSchema).default([]),
  warn: z.array(warnRuleSchema).default([]),
});

export const warnRuleSchema = z.object({
  type: z.literal("trade_value_diff"),
  /** Warn when |sent - received| / max exceeds this percentage. */
  thresholdPct: z.number().min(0).max(100),
});

